// PopupEl is gpui_kit::base::Popup.
type PopupEl struct{ n *node }

func (e PopupEl) node() *node { return e.n }

// Popup is <gpui_kit::base::Popup>::new.
func Popup(id ID, trigger Element, st ...Style) PopupEl {
	useBasePopup()
	n := newNode(350)
	o := nodeArgs(n)
	putID(o, id)
	o.u32(take(trigger))
	tokens(n, st)
	return PopupEl{n}
}

// Anchor is <gpui_kit::base::Popup>::anchor.
func (e PopupEl) Anchor(anchor Anchor) PopupEl {
	o := op(e.n, 256)
	o.u16(uint16(anchor))
	return e
}

// Content is <gpui_kit::base::Popup>::content.
func (e PopupEl) Content(content Element) PopupEl {
	o := op(e.n, 257)
	o.u32(take(content))
	return e
}

// Offset is <gpui_kit::base::Popup>::offset.
func (e PopupEl) Offset(offset float32) PopupEl {
	o := op(e.n, 258)
	o.f32(offset)
	return e
}

// OnPosition is <gpui_kit::base::Popup>::on_position.
func (e PopupEl) OnPosition(callback func(cx *Cx, e Event117)) PopupEl {
	o := op(e.n, 259)
	o.u32(register(callback, 117))
	return e
}

