// TabsEl is gpui_kit::base::Tabs.
type TabsEl struct{ n *node }

func (e TabsEl) node() *node { return e.n }

// Tabs is <gpui_kit::base::Tabs>::new.
func Tabs(id ID, st ...Style) TabsEl {
	useBaseTabs()
	n := newNode(400)
	o := nodeArgs(n)
	putID(o, id)
	tokens(n, st)
	return TabsEl{n}
}

