// ToastStack is <gpui_kit::base::ToastStack>::new.
func ToastStack(id ID, state ToastStackState, st ...Style) ToastStackEl {
	useBaseToast()
	n := newNode(825)
	o := nodeArgs(n)
	putID(o, id)
	putObj(o, state.h)
	tokens(n, st)
	return ToastStackEl{n}
}

